export type CatalogProjectRow = {
  id: number;
  name: string;
  badge: string;
  price?: string;
  area?: number;
  dimensions?: string;
  sourceSlug: string;
  sourceVerifiedFields?: Project["sourceVerifiedFields"];
  image?: string;
  gallery?: Project["gallery"];
  productType?: Project["productType"];
  useCases?: Project["useCases"];
  beds?: number;
  kitchens?: number;
  baths?: number;
  floors?: number;
  term?: string;
  rooms?: string;
  style?: string;
  technology?: string;
  completion?: string;
  insulation?: string;
  landSize?: string;
  features?: string[];
  descriptionLong?: string;
  steamRoomArea?: string;
  steamRoomFinish?: string;
  floorFinish?: string;
  suitableFor?: string[];
  hasShowroom?: boolean;
  hasInstallment?: boolean;
};

export type CatalogDefaults = Pick<
  Project,
  "manufacturerId" | "city" | "purpose" | "technology" | "completion" | "insulation" | "term"
> & {
  manufacturerName: string;
  sourceBaseUrl: string;
  fallbackImage?: string;
};

/**
 * Преобразует компактную выгрузку каталога производителя в общую модель сайта.
 * Для нового производителя меняются только строки источника и общие настройки,
 * а карточки, фильтры, профиль, SEO-маршруты и счётчики строятся автоматически.
 * sourceBaseUrl и sourceSlug обязательны: без официального источника проект не
 * должен получать сгенерированные факты. Расширенное описание применяется ко
 * всем проверенным проектам Екатеринбурга по единому шаблону.
 * Неизвестные необязательные поля нужно оставлять пустыми, а не угадывать.
 */
export const createManufacturerCatalogProjects = (
  defaults: CatalogDefaults,
  rows: CatalogProjectRow[],
): Project[] => rows.map((row) => {
  const isBath = row.productType === "bath";
  const price = row.price ?? "по запросу";
  const areaLabel = row.area?.toLocaleString("ru-RU", { maximumFractionDigits: 2 });
  const dimensions = row.dimensions ? ` Размеры: ${row.dimensions}.` : "";
  const areaDescription = areaLabel ? ` площадью ${areaLabel} м²` : "";
  const description = `${row.badge}${areaDescription} от «${defaults.manufacturerName}».${dimensions}`;
  const generatedDescriptionLong = [
    `${row.name}: ${row.badge.toLocaleLowerCase("ru")}${areaDescription}${row.dimensions ? ` и габаритами ${row.dimensions}` : ""}.`,
    row.rooms ? `В характеристиках производителя указана планировка: ${row.rooms.toLocaleLowerCase("ru")}.` : "Планировку необходимо уточнить у производителя.",
    row.insulation ? `Утепление: ${row.insulation}.` : "Толщина утепления на странице проекта не опубликована.",
    row.term ? `Указанный срок производства: ${row.term.replace(/\s*д\.$/u, " дней")}.` : "Срок производства необходимо уточнить у производителя.",
    row.completion ? `Стартовая стоимость относится к варианту «${row.completion.replace(/^Комплектация\s+«|»$/gu, "") }».` : "Состав комплектации необходимо уточнить у производителя.",
  ].join(" ");

  return {
    id: row.id,
    name: row.name,
    badge: row.badge,
    price,
    area: areaLabel ? `${areaLabel} м²` : "По запросу",
    area_m2: row.area,
    beds: row.beds ?? 0,
    kitchens: row.kitchens,
    baths: row.baths ?? 0,
    floors: row.floors ?? 0,
    // A manufacturer-wide marketing promise is not a verified build term for
    // every catalog item. Publish a term only when the source row states it.
    term: row.term ?? "по запросу",
    rooms: row.rooms ?? "Планировка на сайте производителя",
    purpose: defaults.purpose,
    city: defaults.city,
    manufacturerId: defaults.manufacturerId,
    sourceUrl: new URL(row.sourceSlug, defaults.sourceBaseUrl).toString(),
    sourceVerifiedFields: row.sourceVerifiedFields,
    productType: row.productType ?? "house",
    useCases: row.useCases,
    dimensions: row.dimensions,
    steamRoomArea: row.steamRoomArea,
    steamRoomFinish: row.steamRoomFinish,
    floorFinish: row.floorFinish,
    description,
    descriptionLong: row.descriptionLong ?? generatedDescriptionLong,
    gallery: row.gallery ?? [{ image: row.image ?? defaults.fallbackImage!, type: "photo", fit: "contain", blur: true }],
    likes: 0,
    rating: 0,
    suitableFor: row.suitableFor ?? [],
    technology: row.technology ?? defaults.technology,
    completion: row.completion ?? defaults.completion,
    insulation: row.insulation ?? defaults.insulation,
    features: row.features ?? [],
    style: row.style ?? "Не указан",
    landSize: row.landSize ?? "по проекту",
    hasRealPhotos: Boolean(row.image || row.gallery?.length),
    hasShowroom: row.hasShowroom ?? false,
    hasInstallment: row.hasInstallment ?? false,
  };
});

