const byggeGallery = (
  previewImage: string,
  resourceId: number,
  files: string[],
  planFiles: string[] = [],
): Project["gallery"] => {
  const plans = new Set(planFiles);

  return files.map((file, index) => {
    const isPlan = plans.has(file);
    return {
      image: index === 0 ? previewImage : `https://bygge.ru/assets/images/resources/${resourceId}/big/${file}`,
      type: isPlan ? "plan" : "photo",
      fit: "contain",
      ...(isPlan ? {} : { blur: true, edgeBleed: true }),
    };
  });
};

